uint8_t SwapBitInByte(uint8_t val) {
  val = ( ( val & 0x55 ) << 1 ) | ( ( val & 0xAA ) >> 1 );
  val = ( ( val & 0x33 ) << 2 ) | ( ( val & 0xCC ) >> 2 );
  val = ( ( val & 0x0F ) << 4 ) | ( ( val & 0xF0 ) >> 4 );
  return val;
